import java.io.*;

public class Main {

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        int n = nextInt(in);
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt(in);
        }

        // Um aluno i é visível se e somente se a[i] > max(a[i+1..n-1]).
        // Percorrendo da direita para a esquerda, mantemos o máximo do sufixo:
        // se a[i] > maxSufixo -> visível (e atualiza o máximo);
        // caso contrário (a[i] <= maxSufixo) -> invisível.
        int invisible = 0;
        int max = 0; // alturas são >= 1, então 0 funciona como -infinito
        for (int i = n - 1; i >= 0; i--) {
            if (a[i] > max) {
                max = a[i];
            } else {
                invisible++;
            }
        }

        System.out.print(invisible);
    }

    private static int nextInt(DataInputStream in) throws IOException {
        int ret = 0;
        int b = in.read();
        while (b != -1 && (b < '0' || b > '9')) {
            b = in.read();
        }
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = in.read();
        }
        return ret;
    }
}
